PF_COM_FDOT = 0x03  # palette fade out
PF_COM_SE = 0x80  # 0x80|n play sound effect n (disabled in tutorial ROM)
PF_COM_BGM = 0xA0  # 0xA0|n play music n (disabled in tutorial ROM)
PF_COM_VRAM = 0xC0  # 0xC0|adrH, adrL, data: poke one VRAM byte
PF_DAT_VRAM = 0x80  # bulk data mode: VRAM block
PF_DAT_RAM = 0x81  # bulk data mode: CPU RAM block
PF_DAT_STEP = 0x82  # bulk data mode: leave and switch console step
FC_COM_BUF_SIZE16 = 16  # bytes of the mailbox the v1 command executor parses (2..15)
