APU_PAIRS_MAX_V1 = 23  # pairs that fit: (64 - 16 - 2) / 2, terminator 0xFF
APU_PAIRS_MAX_NMI_V1 = 24  # pairs the tutorial NMI replay loop will apply (0x30 bytes)

# --- opcodes-v1: console -> cartridge, single bytes written to $2007 ---
FP_COM_ACK = 0x0F  # unused on both sides
FP_COM_NAK = 0x1F  # unused on both sides
FP_COM_VER = 0x2F  # request the 14-byte boot-ROM build stamp
FP_COM_ROM = 0x3F  # + page: request 256 bytes of the boot ROM image
FP_COM_LOG = 0xBF  # + up to 7 bytes: print on the cartridge serial console
FP_COM_DRQ = 0xCF  # bulk data mode: request next block header
FP_COM_DLD = 0xDF  # + page: bulk data mode: request one 256-byte page
FP_COM_RST = 0xEF  # restart the cartridge firmware
FP_COM_INI = 0xFF  # + stage: initialise the cartridge

